mapper.select:
SELECT dor.id, dor.staff_name, dor.staff_badge, dor.opt_user, dor.staff_sex, dor.room_id, nvl( t3.ALIAS_NAME, t3.ROOM_NAME ) room_name, dor.bed_number, dor.park_name, dor.dormitory_name, dor.dormitory_type_name, dor.create_time, sta.comp_name, sta.dep_name, sta.job_name, sta.status, dor.comp_name AS dor_comp_name, dor.dep_name AS dor_dep_name, dor.job_name AS dor_job_name, sta.jche_name FROM smt_dormitory_staff dor LEFT JOIN smt_staff sta ON dor.staff_id = sta.id LEFT JOIN smt_dormitory_room t3 ON dor.room_id = t3.id
and dor.staff_name LIKE CONCAT(CONCAT('%',#{query.staffName}),'%')
and dor.staff_badge LIKE CONCAT(CONCAT('%',#{query.staffBadge}),'%')
and (dor.comp_name LIKE CONCAT(CONCAT('%',#{query.compName}),'%') or sta.comp_name LIKE CONCAT(CONCAT('%',#{query.compName}),'%') )
and (sta.sex =#{query.sex } or dor.STAFF_SEX=#{query.sex })
and dor.park_id =#{query.parkId }
and dor.dormitory_id =#{query.dormitoryId }
and dor.dormitory_id in
#{item}
and dor.floor_id =#{query.floorId }
and dor.room_id =#{query.roomId }
and sta.jche_id =#{query.jcheId }
and dor.PARK_ID in
#{item}
AND dor.CREATE_TIME between to_date(#{query.startTime},'yyyy-mm-dd hh24:mi:ss') and to_date(#{query.endTime},'yyyy-mm-dd hh24:mi:ss')
ORDER BY dor.floor_name,dor.room_name,dor.bed_number

SELECT D.DORMITORY_ID, D.FLOOR_ID, D.ROOM_ID, D.CREATE_TIME, D.PARK_ID, D.STAFF_BADGE BADGE, D.STAFF_NAME NAME, S.PHONE, D.IS_STAFF FROM SMT_DORMITORY_STAFF D LEFT JOIN SMT_STAFF S ON D.STAFF_ID = S.ID
and d.park_id = #{parkId}
and to_char( d.create_time,'yyyy-mm-dd') = #{createTime}
order by d.create_time desc
